// === Tab: mySketch ===
let ctx;
let centerX, centerY;
let cellCount = 50;
let cells = [];
let balls = [];
let colors = ['#e6302b', '#36ad63', '#fbd400', '#ffffff', '#232323', '#f654a9', '#2B50AA'];

function setup() {
    createCanvas(800, 800);
    rectMode(CENTER);
    colorMode(HSB, 360, 100, 100, 100);
    ctx = drawingContext;
    centerX = width / 2;
    centerY = height / 2;
    let gridArea = width;
    let cellSize = gridArea / cellCount;
    let w = cellSize;
    for (let row = 0; row < cellCount; row++) {
        let y = row * cellSize + cellSize / 2 + (height - gridArea) / 2;
        for (let col = 0; col < cellCount; col++) {
            let x = col * cellSize + cellSize / 2 + (width - gridArea) / 2;
            let clr1 = random(colors);
            let clr2 = random(colors);
            cells.push({ x: x, y: y, w: w, c1: clr1, c2: clr2 });
        }
    }
    for (let i = 0; i < 15; i++) {
        let x = random(width);
        let y = random(height);
        let d = width * random(0.2, 0.08);
        balls.push(new Ball(x, y, d));
    }
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

    background('#ffffff');
    noStroke();
    for (let c of cells) {
        let isInside = false;
        let clr;
        for (let b of balls) {
            let dst = dist(b.x, b.y, c.x, c.y);
            if (dst < b.radius) {
                isInside = true;
                clr = b.c;
                break;
            }
        }
        if (isInside) {
            fill(c.c2);
            circle(c.x, c.y, c.w * 0.9);
            fill(c.c1);
            circle(c.x, c.y, c.w * 0.5);
        } else {
            fill(90);
            circle(c.x, c.y, c.w * 0.9);
            fill(80);
            circle(c.x, c.y, c.w * 0.5);
        }
    }
    for (let b of balls) {
        b.update();
    }
    for (let i = 0; i < balls.length; i++) {
        let c1 = balls[i];
        for (let j = i + 1; j < balls.length; j++) {
            let c2 = balls[j];
            let dx = c2.x - c1.x;
            let dy = c2.y - c1.y;
            let distance = sqrt(dx * dx + dy * dy);
            let minDist = c1.d + c2.d;
            if (distance < minDist && distance > 0) {
                let force = (minDist - distance) * 1.5;
                let nx = dx / distance;
                let ny = dy / distance;
                let accel1 = force / c1.mass;
                let accel2 = force / c2.mass;
                c1.vx -= accel1 * nx;
                c1.vy -= accel1 * ny;
                c2.vx += accel2 * nx;
                c2.vy += accel2 * ny;
            }
        }
    }

  pop();
}

class Ball {
    constructor(x, y, d) {
        this.x = x;
        this.y = y;
        this.d = d;
        this.vx = random(-1, 1) * width * 0.001;
        this.vy = random(-1, 1) * width * 0.001;
        this.c = random(colors);
        this.radius = this.d / 2;
        this.mass = this.d * this.d;
    }
    show() {
    }
    update() {
        this.x += this.vx;
        this.y += this.vy;
        if (this.x <= this.radius || width - this.radius <= this.x) {
            this.vx *= -1;
        }
        if (this.y <= this.radius || height - this.radius <= this.y) {
            this.vy *= -1;
        }
        this.x = constrain(this.x, this.radius, width - this.radius);
        this.y = constrain(this.y, this.radius, height - this.radius);
    }
    run() {
        this.show();
        this.update();
    }
}

